export type ApplicationErrorKind = 'not_found' | 'validation';

/** Raised when a use case cannot be carried out with the given input. */
export class ApplicationError extends Error {
  constructor(
    message: string,
    readonly kind: ApplicationErrorKind,
  ) {
    super(message);
    this.name = 'ApplicationError';
  }
}

export class NotFoundError extends ApplicationError {
  constructor(resource: string, id: string) {
    super(`${resource} ${id} not found`, 'not_found');
    this.name = 'NotFoundError';
  }
}

export class UnknownAssigneeError extends ApplicationError {
  constructor(userId: string) {
    super(`Assignee ${userId} is not an existing user`, 'validation');
    this.name = 'UnknownAssigneeError';
  }
}

=====SOURCE-END=====

